.xpb{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Helvetica Neue",Arial,sans-serif;color:#191919;line-height:1.6;max-width:1100px;margin:0 auto}
.xpb *{box-sizing:border-box}
.xpb img{width:100%;height:auto;display:block;border-radius:12px}
.xpb section{padding:48px 20px;text-align:center}
.xpb .alt{background:#f5f5f5;border-radius:16px}
.xpb h2{font-size:30px;font-weight:700;margin:0 0 12px;line-height:1.25}
.xpb h3{font-size:20px;font-weight:600;margin:0 0 6px}
.xpb p{font-size:16px;color:#555;max-width:720px;margin:0 auto 24px}
.xpb .tag{color:#ff6900;font-weight:600;font-size:14px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:8px;display:block}
.xpb .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:32px 0 0}
.xpb .stat b{display:block;font-size:30px;color:#ff6900;font-weight:700}
.xpb .stat span{font-size:14px;color:#555}
.xpb .grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:24px}
.xpb .card{background:#fff;border-radius:14px;padding:24px 16px}
.xpb .card b{display:block;font-size:34px;color:#ff6900}
.xpb .prot{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:24px;text-align:left}
.xpb .prot div{background:#fff;border-radius:10px;padding:12px 14px;font-size:14px}
.xpb table{width:100%;border-collapse:collapse;text-align:left;font-size:15px;margin-top:16px}
.xpb td{padding:14px 10px;border-bottom:1px solid #e5e5e5;vertical-align:top}
.xpb td:first-child{color:#888;width:38%}
.xpb details{text-align:left;border-bottom:1px solid #e5e5e5;padding:16px 4px}
.xpb summary{font-weight:600;cursor:pointer;font-size:16px}
.xpb details p{margin:10px 0 0;text-align:left;max-width:none}
.xpb .note{font-size:12px;color:#999;margin-top:16px}
@media(max-width:700px){
.xpb section{padding:36px 14px}
.xpb h2{font-size:24px}
.xpb .stats{grid-template-columns:repeat(2,1fr)}
.xpb .grid3,.xpb .prot{grid-template-columns:1fr}
}

